 function shrine(s,b,now,selected,festival){let d=BY_ID[s.deity],[x,y]=b.map.plots[s.plot],img=images[s.level===3?'exalted':s.level===2?'honoured':'shrines'];let w=s.level===1?73:s.level===2?95:108,h=s.level===1?128:s.level===2?141:155;c.save();if(s.level>1){c.fillStyle=d.colour+'18';c.beginPath();c.ellipse(x,y-40,w*.62,h*.55,0,0,Math.PI*2);c.fill();}tile(img,d.atlas,4,2,x,y-h/2+4,w,h);if(festival)tile(images.restoration,6,4,2,x,y-h*.68,w+18,40,.95);label(d.name,x,y+20,d.colour,'#fff3dcd9',12);for(let i=0;i<s.level;i++){c.fillStyle='#d09c38';c.beginPath();c.arc(x+(i-(s.level-1)/2)*12,y+42,4,0,Math.PI*2);c.fill();}if(s.plot===selected){c.setLineDash([5,5]);ring(x,y-35,w*.65,d.colour,2);c.setLineDash([]);}c.restore();}
