 let figures=[...b.shrines.map(s=>({kind:'shrine',y:b.map.plots[s.plot][1],s})),...b.enemies.map(e=>({kind:'enemy',y:b.pos(e).y,e}))].sort((a,z)=>a.y-z.y);for(let f of figures){if(f.kind==='shrine')shrine(f.s,b,now,selectedPlot,festival);else enemy(f.e,b,now);}
